fn skyFrag(uv: vec2<f32>) -> vec4<f32> {
    let tm = camera.simTime;
    let fade = clamp(tm / 15.0, 0.0, 1.0);
    let sPos = 1.0 - uv.y;
    let horizon = 0.38;
    let sunX = 0.5;
    let sunS = 0.405;
    let dx = (uv.x - sunX) * camera.aspect;
    let dy = sPos - sunS;
    let dist = length(vec2<f32>(dx, dy));
    let e = clamp((sPos - horizon) / (1.0 - horizon), 0.0, 1.0);
    let topA = vec3<f32>(0.19, 0.21, 0.42);
    let topB = vec3<f32>(0.09, 0.11, 0.25);
    let topC = topA + (topB - topA) * fade;
    let midA = vec3<f32>(0.63, 0.38, 0.47);
    let midB = vec3<f32>(0.36, 0.25, 0.41);
    let midC = midA + (midB - midA) * fade;
    let lowA = vec3<f32>(1.02, 0.50, 0.27);
    let lowB = vec3<f32>(0.62, 0.30, 0.30);
    let lowC = lowA + (lowB - lowA) * fade;
    var col = lowC + (midC - lowC) * smoothstep(0.0, 0.38, e);
    col = col + (topC - col) * smoothstep(0.30, 1.0, e);
    let sunCore = exp(-dist * dist * 110.0) * 1.6;
    let sunMid = exp(-dist * dist * 22.0) * 0.65;
    let sunWide = exp(-dist * 7.0) * 0.28;
    let glowAmt = sunCore + sunMid + sunWide;
    let sunWarm = vec3<f32>(1.45, 0.72, 0.36);
    let sunCool = vec3<f32>(0.85, 0.42, 0.34);
    let sunC = sunWarm + (sunCool - sunWarm) * fade;
    let sunDim = 1.0 - 0.55 * fade;
    col = col + sunC * glowAmt * sunDim;
    let horizBand = exp(-abs(sPos - horizon) * 12.0);
    let fogA = vec3<f32>(0.74, 0.62, 0.68);
    let fogB = vec3<f32>(0.46, 0.40, 0.50);
    let fogC = fogA + (fogB - fogA) * fade;
    let bandAmt = horizBand * 0.55 * smoothstep(0.9, 0.15, dist);
    col = col + (fogC - col) * bandAmt;
    let streak = exp(-abs(dy) * 22.0) * exp(-abs(dx) * 3.2);
    col = col + vec3<f32>(0.95, 0.45, 0.28) * streak * 0.35 * sunDim;
    let below = 1.0 - smoothstep(horizon - 0.02, horizon + 0.02, sPos);
    let groundA = vec3<f32>(0.30, 0.26, 0.33);
    let groundB = vec3<f32>(0.16, 0.15, 0.22);
    let groundC = groundA + (groundB - groundA) * fade;
    col = col + (groundC - col) * below * 0.85;
    let dith = fract(sin(dot(uv, vec2<f32>(12.9898, 78.233))) * 43758.5453);
    col = col + (dith - 0.5) * 0.028;
    return vec4<f32>(col, 1.0);
}

fn driftFog(index: u32) {
    let tt = camera.simTime;
    let rr = f32(index / 6u);
    let cc = f32(index % 6u);
    let fi = f32(index);
    let h1 = fract(sin(fi * 12.9898) * 43758.5453);
    let h2 = fract(sin(fi * 78.233 + 17.13) * 24634.4689);
    let h3 = fract(sin(fi * 39.425 + 43.31) * 56445.2341);
    let pha = fi * 2.399963 + h1 * 6.283185;
    let spd = 0.55 + 0.45 * h2;
    let span = 96.0;
    let baseX = (cc - 2.5) * 14.0 + (rr - 1.5) * 6.0 + h3 * 6.0;
    let rawX = baseX + tt * spd + pha * 1.5;
    let wrapped = rawX - span * floor(rawX / span);
    let px = -48.0 + wrapped;
    let pz = -7.0 - rr * 13.5 - h1 * 8.0;
    let py = 1.6 + rr * 1.35 + h2 * 2.4 + sin(tt * 0.16 + pha * 1.7) * 0.7 + sin(tt * 0.05 + pha) * 0.4;
    let ang = (h1 - 0.5) * 0.5 + 0.06 * sin(tt * 0.1 + pha);
    let sy = sin(ang * 0.5);
    let cy = cos(ang * 0.5);
    let sx = 17.0 + h2 * 11.0 + sin(tt * 0.12 + pha * 2.0) * 1.5;
    let syy = 2.6 + h3 * 3.2 + sin(tt * 0.18 + pha) * 0.5;
    let cr = 0.74 + 0.08 * h1;
    let cg = 0.69 + 0.07 * h2;
    let cb = 0.8 + 0.07 * h3;
    let base = index * B_fog_STRIDE;
    b_fog[base + 0u] = 0.0;
    b_fog[base + 1u] = px;
    b_fog[base + 2u] = py;
    b_fog[base + 3u] = pz;
    b_fog[base + 4u] = 0.0;
    b_fog[base + 5u] = sy;
    b_fog[base + 6u] = 0.0;
    b_fog[base + 7u] = cy;
    b_fog[base + 8u] = sx;
    b_fog[base + 9u] = syy;
    b_fog[base + 10u] = 1.0;
    b_fog[base + 11u] = cr;
    b_fog[base + 12u] = cg;
    b_fog[base + 13u] = cb;
}

fn placeFog(index: u32) {
    let base = index * B_fog_STRIDE;
    let row = index / 6u;
    let col = index % 6u;
    let cf = f32(col);
    let rf = f32(row);
    let seed = f32(index) * 12.9898 + 78.233;
    let j1 = fract(sin(seed) * 43758.5453) - 0.5;
    let j2 = fract(sin(seed * 1.7 + 13.1) * 24634.6349) - 0.5;
    var zBase = 2.0;
    var yBase = 2.5;
    if (row == 1u) {
        zBase = -18.0;
        yBase = 4.2;
    }
    if (row == 2u) {
        zBase = -38.0;
        yBase = 6.2;
    }
    if (row == 3u) {
        zBase = -60.0;
        yBase = 8.5;
    }
    let xPos = (cf - 2.5) * 15.0 + (rf - 1.5) * 5.0 + j1 * 7.0;
    let zPos = zBase + j2 * 6.0;
    let yPos = yBase + 0.7 * sin(cf * 1.3 + rf * 2.1) + j1 * 1.2;
    let sx = 19.0 + rf * 2.5 + j2 * 4.0 + cf * 0.4;
    let sy = 9.0 + rf * 1.8 + j1 * 3.0;
    let warm = 1.0 - rf * 0.18;
    let rC = 0.80 + 0.06 * warm + j1 * 0.04;
    let gC = 0.75 + 0.03 * warm + j2 * 0.04;
    let bC = 0.84 + j1 * 0.03;
    b_fog[base + 0u] = 0.0;
    b_fog[base + 1u] = xPos;
    b_fog[base + 2u] = yPos;
    b_fog[base + 3u] = zPos;
    b_fog[base + 4u] = -0.70710678;
    b_fog[base + 5u] = 0.0;
    b_fog[base + 6u] = 0.0;
    b_fog[base + 7u] = 0.70710678;
    b_fog[base + 8u] = sx;
    b_fog[base + 9u] = sy;
    b_fog[base + 10u] = 1.0;
    b_fog[base + 11u] = rC;
    b_fog[base + 12u] = gC;
    b_fog[base + 13u] = bC;
}

fn hashOne(seed: u32) -> f32 {
    return fract(sin(f32(seed) * 12.9898 + 78.233) * 43758.5453);
}
fn placeHills(index: u32) {
    let row = index / 64u;
    let col = index % 64u;
    let r0 = hashOne(index * 3u + 11u);
    let r1 = hashOne(index * 3u + 101u);
    let r2 = hashOne(index * 3u + 501u);
    var halfW = 75.0;
    var zBase = 0.0;
    var yBase = -7.0;
    var sxBase = 14.0;
    var syBase = 7.0;
    var szBase = 14.0;
    var cr = 0.11;
    var cg = 0.17;
    var cb = 0.16;
    if (row == 1u) {
        halfW = 100.0;
        zBase = -45.0;
        yBase = -8.0;
        sxBase = 20.0;
        syBase = 10.0;
        szBase = 18.0;
        cr = 0.16;
        cg = 0.2;
        cb = 0.24;
    }
    if (row == 2u) {
        halfW = 140.0;
        zBase = -95.0;
        yBase = -9.0;
        sxBase = 28.0;
        syBase = 13.0;
        szBase = 24.0;
        cr = 0.24;
        cg = 0.23;
        cb = 0.32;
    }
    if (row == 3u) {
        halfW = 190.0;
        zBase = -160.0;
        yBase = -11.0;
        sxBase = 38.0;
        syBase = 17.0;
        szBase = 32.0;
        cr = 0.32;
        cg = 0.29;
        cb = 0.4;
    }
    let nx = (f32(col) + 0.5) / 64.0 * 2.0 - 1.0;
    let gap = exp(-nx * nx * 5.0);
    var xPos = nx * halfW + (r0 - 0.5) * 10.0;
    var zPos = zBase + (r1 - 0.5) * 14.0;
    var yPos = yBase + sin(nx * 3.1 + f32(row) * 1.7) * 1.8 + (r2 - 0.5) * 2.2;
    yPos = yPos - gap * (2.0 + f32(row) * 0.9);
    var sx = sxBase * (0.8 + 0.55 * r0);
    var sy = syBase * (0.8 + 0.45 * r1);
    var sz = szBase * (0.9 + 0.35 * r2);
    sy = sy * (1.0 - gap * 0.35);
    xPos = xPos + gap * (r0 - 0.5) * 6.0;
    let base = index * B_hills_STRIDE;
    b_hills[base + 0u] = 0.0;
    b_hills[base + 1u] = xPos;
    b_hills[base + 2u] = yPos;
    b_hills[base + 3u] = zPos;
    b_hills[base + 4u] = 0.0;
    b_hills[base + 5u] = 0.0;
    b_hills[base + 6u] = 0.0;
    b_hills[base + 7u] = 1.0;
    b_hills[base + 8u] = sx;
    b_hills[base + 9u] = sy;
    b_hills[base + 10u] = sz;
    b_hills[base + 11u] = cr;
    b_hills[base + 12u] = cg;
    b_hills[base + 13u] = cb;
}
